    INSERT INTO topics (title, slug, year_id, section, "order")
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the most appropriate next step in the history-taking of a 2-week-old infant who is presenting for a well-child check?', '["Review the prenatal and birth history", "Focus solely on current feeding patterns", "Ask about school performance", "Inquire about teenage peer relationships"]', 0, 'In neonatal and early infant visits, the prenatal and birth history (APGARs, complications, maternal health) is critical. (Nelson)'),
    (v_topic_id, '2: At what age should a pediatrician start measuring blood pressure as part of a routine well-child physical exam?', '["At birth", "1 year", "3 years", "5 years"]', 2, 'Routine blood pressure screening begins at age 3 for healthy children. (AAP Guidelines)'),
    (v_topic_id, '3: Which of the following is the most accurate method for assessing a child''s growth over time?', '["Single weight measurement", "Single height measurement", "Plotting measurements on age-appropriate growth charts", "Comparing the child to siblings"]', 2, 'Growth charts allow for the assessment of growth velocity and trends, which are more important than single data points. (Harriet Lane)'),
    (v_topic_id, '4: An 18-month-old child presents with a height and weight below the 3rd percentile. What is the most common cause of non-organic failure to thrive?', '["Celiac disease", "Cystic fibrosis", "Inadequate caloric intake due to psychosocial factors", "Growth hormone deficiency"]', 2, 'Psychosocial factors leading to inadequate intake are the most common causes of FTT. (Case Files)'),
    (v_topic_id, '5: Which of the following is the recommended primary source of nutrition for the first 6 months of life?', '["Whole cow''s milk", "Infant formula with added cereal", "Exclusive breastfeeding", "Water and fruit juice"]', 2, 'The AAP and WHO recommend exclusive breastfeeding for the first 6 months. (Nelson)'),
    (v_topic_id, '6: A 4-day-old neonate presents with a 10% weight loss from birth. The infant is breastfeeding every 2-3 hours. What is the appropriate management?', '["Immediate supplementation with formula", "Hospitalization for failure to thrive", "Reassure the parents that up to 10% weight loss is normal in the first week", "Switch to soy milk"]', 2, 'Term neonates can lose up to 10% of their birth weight but should regain it by 10-14 days. (Harriet Lane)'),
    (v_topic_id, '7: What is the maintenance fluid requirement (using the Holliday-Segar method) for a child weighing 25 kg?', '["1000 mL/day", "1500 mL/day", "1600 mL/day", "2500 mL/day"]', 2, '1000 (for first 10kg) + 500 (for next 10kg) + 100 (for remaining 5kg: 5x20) = 1600 mL/day. (Nelson)'),
    (v_topic_id, '8: A 10-kg child requires maintenance fluids. What is the hourly rate?', '["10 mL/hr", "20 mL/hr", "40 mL/hr", "60 mL/hr"]', 2, 'The 4-2-1 rule: 4 mL/kg for the first 10kg = 40 mL/hr. (Harriet Lane)'),
    (v_topic_id, '9: Which of the following is the most sensitive clinical indicator of dehydration in a child?', '["Sunken fontanelle", "Dry mucous membranes", "Prolonged capillary refill and skin turgor", "Absence of tears"]', 2, 'Capillary refill, skin turgor, and respiratory pattern are high-yield indicators of dehydration severity. (Case Files)'),
    (v_topic_id, '10: A 2-year-old child presents with mild dehydration from viral gastroenteritis. What is the preferred initial method of rehydration?', '["IV Normal Saline bolus", "IV D5 1/2 Normal Saline", "Oral Rehydration Therapy (ORT)", "Apple juice and water"]', 2, 'ORT is the first-line treatment for mild to moderate dehydration. (AAP)'),
    (v_topic_id, '11: What is the standard dose of an IV fluid bolus for a child in hypovolemic shock?', '["5 mL/kg", "10 mL/kg", "20 mL/kg", "50 mL/kg"]', 2, '20 mL/kg of an isotonic crystalloid (NS or LR) is the standard bolus. (PALS)'),
    (v_topic_id, '12: At what age should head circumference measurements typically stop during routine well-child visits?', '["1 year", "2 years", "5 years", "10 years"]', 1, 'Head circumference is routinely measured until age 2, as most brain growth occurs by then. (Nelson)'),
    (v_topic_id, '13: Which of the following is an absolute contraindication to breastfeeding?', '["Maternal Hepatitis B infection", "Maternal Hepatitis C infection", "Maternal HIV infection (in developed countries)", "Maternal common cold"]', 2, 'In developed countries where safe alternatives exist, HIV is a contraindication. (Nelson)'),
    (v_topic_id, '14: A child with moderate dehydration has a weight loss of approximately:', '["3%", "6-9%", "15%", "20%"]', 1, 'Mild is <5%, moderate is 6-9%, and severe is >=10%. (Harriet Lane)'),
    (v_topic_id, '15: What is the most common cause of hyponatremia in a hospitalized child receiving IV fluids?', '["Inadequate salt intake", "Excessive sweating", "SIADH or use of hypotonic fluids", "Renal failure"]', 2, 'The use of hypotonic fluids (e.g., 0.25% NS) in the setting of ADH release is a major cause. (Nelson)'),
    (v_topic_id, '16: Which Vitamin is NOT found in adequate amounts in breast milk and must be supplemented from birth?', '["Vitamin A", "Vitamin C", "Vitamin D", "Vitamin K"]', 2, 'Breastfed infants require 400 IU of Vitamin D daily. (AAP)'),
    (v_topic_id, '17: Why is whole cow''s milk avoided before 12 months of age?', '["It causes obesity", "It is associated with iron-deficiency anemia and intestinal blood loss", "It is too expensive", "It has too much Vitamin D"]', 1, 'Cow''s milk can cause microscopic intestinal bleeding and lacks sufficient iron for infants. (Case Files)'),
    (v_topic_id, '18: What is the caloric content of standard infant formula?', '["10 kcal/oz", "15 kcal/oz", "20 kcal/oz", "30 kcal/oz"]', 2, 'Standard formula and breast milk provide approximately 20 kcal/oz. (Harriet Lane)'),
    (v_topic_id, '19: A 4-year-old child presents with "night terrors." What is the appropriate management?', '["Start low-dose benzodiazepines", "Perform an overnight sleep study", "Reassure parents and ensure adequate sleep hygiene", "Refer to child psychiatry"]', 2, 'Night terrors are common and benign; they occur in non-REM sleep, and the child usually doesn''t remember them. (Nelson)'),
    (v_topic_id, '20: At what age does the first dental visit typically occur?', '["1 year or when the first tooth erupts", "3 years", "5 years", "When the first permanent tooth erupts"]', 0, 'The AAP recommends a dental home be established by age 1. (Nelson)'),
    (v_topic_id, '21: Which of the following is the most common cause of accidental poisoning in children?', '["Lead paint", "Cleaning products and medications", "Spider bites", "Spoiled food"]', 1, 'Household products and meds are the leading causes of ingestion. (Case Files)'),
    (v_topic_id, '22: What is the classic physical exam finding for a child with developmental dysplasia of the hip (DDH) under 3 months of age?', '["Limping", "Positive Ortolani and Barlow maneuvers", "Unequal leg length", "Pain on internal rotation"]', 1, 'Ortolani (reduction) and Barlow (dislocation) are the gold standard for early screening. (Nelson)'),
    (v_topic_id, '23: Which of the following is a "red flag" for developmental delay in a 6-month-old?', '["Not crawling", "Not sitting unsupported", "Persistent primitive reflexes (e.g., Moro)", "Not saying ''Mama'' specifically"]', 2, 'Primitive reflexes should disappear by 4-6 months. (Harriet Lane)'),
    (v_topic_id, '24: A 2-year-old child is in the "negativism" phase, frequently saying "No." This is a sign of:', '["Developing autonomy", "Oppositional Defiant Disorder", "Lack of discipline", "Poor parenting"]', 0, 'Erikson''s stage of Autonomy vs. Shame and Doubt. (Nelson)'),
    (v_topic_id, '25: What is the most appropriate way to assess the height of a child under 2 years of age?', '["Standing height", "Recumbent length (lying down)", "Using a tape measure against a wall", "Estimated by arm span"]', 1, 'Recumbent length is the standard until the child can stand reliably for a stadiometer. (Nelson)'),
    (v_topic_id, '26: Which of the following is a major risk factor for Sudden Infant Death Syndrome (SIDS)?', '["Supine sleeping position", "Maternal smoking", "Breastfeeding", "Use of a pacifier"]', 1, 'Maternal smoking and prone sleeping are significant modifiable risk factors. (Nelson)'),
    (v_topic_id, '27: What is the recommended sleeping position to reduce the risk of SIDS?', '["Prone (on tummy)", "Side-lying", "Supine (on back)", "In a car seat"]', 2, 'The "Back to Sleep" campaign significantly reduced SIDS rates. (AAP)'),
    (v_topic_id, '28: A child presents with "breath-holding spells" triggered by anger or pain. What is the appropriate management?', '["EEG to rule out seizures", "Iron studies (as spells are associated with iron deficiency)", "Behavioral therapy", "Anticonvulsants"]', 1, 'Breath-holding spells are benign but frequently associated with iron-deficiency anemia. (Nelson)'),
    (v_topic_id, '29: At what age should screening for lead poisoning and anemia typically occur for high-risk children?', '["6 months", "12 months and 24 months", "5 years", "Teens"]', 1, 'Universal or targeted screening is common at 1 and 2 years. (CDC)'),
    (v_topic_id, '30: Which of the following is a common cause of "innocent" heart murmurs in children?', '["Ventricular septal defect", "Still''s murmur", "Tetralogy of Fallot", "Coarctation of the aorta"]', 1, 'Still''s murmur is a common, vibratory, mid-systolic innocent murmur. (Case Files)'),
    (v_topic_id, '31: How is an innocent murmur typically distinguished from a pathologic one?', '["It is always diastolic", "It changes with position and is typically grade II or less", "It is associated with cyanosis", "It requires an immediate Echo"]', 1, 'Innocent murmurs are typically systolic, soft, and change with position (e.g., louder when supine). (Nelson)'),
    (v_topic_id, '32: A child presents with a "stridorous" sound only when breathing in. Where is the likely obstruction?', '["Lower airway (bronchi)", "Upper airway (extra-thoracic)", "Middle airway (intra-thoracic)", "Nose"]', 1, 'Inspiratory stridor indicates upper airway narrowing (e.g., Croup). (Harriet Lane)'),
    (v_topic_id, '33: Expiratory wheezing typically indicates narrowing of the:', '["Upper airway", "Larynx", "Lower airways (bronchi/bronchioles)", "Pharynx"]', 2, 'Wheezing is characteristic of lower airway obstruction like asthma or bronchiolitis. (Case Files)'),
    (v_topic_id, '34: What is the most common cause of acute abdominal pain in children requiring surgery?', '["Intussusception", "Appendicitis", "Meckel diverticulum", "Volvulus"]', 1, 'Appendicitis is the leading surgical cause of abdominal pain in kids. (Nelson)'),
    (v_topic_id, '35: In a child with suspected physical abuse, what is the most important "sentinel" finding?', '["A simple fracture from a fall", "Bruises in non-bony areas (e.g., cheeks, ears, neck) in a non-ambulatory infant", "A clean diaper", "High fever"]', 1, '"Those who don''t cruise, don''t bruise." Any bruise on an infant who can''t move independently is highly suspicious. (Case Files)'),
    (v_topic_id, '36: What is the "triple threat" for an adolescent patient history?', '["Diet, Exercise, Sleep", "Drugs, Sex, Suicide/Safety (HEADSS)", "School, Sports, Social Media", "Books, Movies, Games"]', 1, 'The HEADSS assessment is the standard for adolescent psychosocial screening. (Nelson)'),
    (v_topic_id, '37: At what age can a child typically sit with support?', '["2 months", "6 months", "9 months", "12 months"]', 1, 'Sitting with support (tripod) is a 6-month milestone. (Harriet Lane)'),
    (v_topic_id, '38: A child can pull to stand and cruise along furniture. What is the expected age?', '["6 months", "9 months", "12 months", "15 months"]', 1, 'Cruising is a classic 9-month milestone. (Case Files)'),
    (v_topic_id, '39: A child can stack a tower of 2 cubes. Age?', '["12 months", "15 months", "18 months", "24 months"]', 1, 'Tower of 2 (15m), 3 (18m), 6 (24m). (Nelson)'),
    (v_topic_id, '40: When should the "Moro" reflex disappear?', '["1 month", "4 months", "9 months", "1 year"]', 1, 'Disappears by 3-4 months. (Harriet Lane)'),
    (v_topic_id, '41: A child has a vocabulary of 50 words and 2-word phrases. Age?', '["18 months", "2 years", "3 years", "4 years"]', 1, '2 years = 200 words, 2-word phrases. (Case Files)'),
    (v_topic_id, '42: What is the "Rule of 4s" for speech intelligibility?', '["100% at 4 years", "50% at 2 years", "75% at 3 years", "All of the above"]', 3, 'Intelligibility: 2y (50%), 3y (75%), 4y (100%). (Nelson)'),
    (v_topic_id, '43: A child can ride a tricycle. Age?', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Tricycle = 3 years. (Harriet Lane)'),
    (v_topic_id, '44: A child can hop on one foot. Age?', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Hopping = 4 years. (Case Files)'),
    (v_topic_id, '45: A child can skip. Age?', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Skipping = 5 years. (Nelson)'),
    (v_topic_id, '46: A 2-year-old child should be able to copy what shape?', '["Line", "Circle", "Cross", "Square"]', 0, 'Vertical line (2y), Circle (3y), Cross (4y). (Harriet Lane)'),
    (v_topic_id, '47: A child can draw a person with 3 parts. Age?', '["3 years", "4 years", "5 years", "6 years"]', 1, '3 parts = 4 years; 6 parts = 5 years. (Case Files)'),
    (v_topic_id, '48: What is the most common cause of neonatal jaundice in the first 24 hours of life?', '["Breast milk jaundice", "Physiologic jaundice", "Hemolytic disease (e.g., ABO/Rh incompatibility)", "Biliary atresia"]', 2, 'Jaundice in the first 24 hours is ALWAYS pathologic, often hemolytic. (Nelson)'),
    (v_topic_id, '49: Breast milk jaundice typically appears at what time?', '["First 24 hours", "Days 2-3", "Weeks 1-2", "After 1 month"]', 2, 'Breast milk jaundice is "late" jaundice, peaking at 1-2 weeks. (Harriet Lane)'),
    (v_topic_id, '50: What is the primary concern with extremely high levels of unconjugated bilirubin in a neonate?', '["Liver failure", "Kernicterus (bilirubin encephalopathy)", "Kidney stones", "Pancreatitis"]', 1, 'Unconjugated bilirubin can cross the blood-brain barrier and cause permanent damage. (Case Files)'),
    (v_topic_id, '51: A child presents with a "barking" cough. Diagnosis?', '["Asthma", "Croup", "Epiglottitis", "Pneumonia"]', 1, 'Barking cough = Croup (Laryngotracheobronchitis). (Nelson)'),
    (v_topic_id, '52: What is the classic X-ray finding for Croup?', '["Thumbprint sign", "Steeple sign", "Sail sign", "Honeycombing"]', 1, 'Steeple sign = subglottic narrowing. (Harriet Lane)'),
    (v_topic_id, '53: A child presents with high fever, drooling, and a "tripod" position. Diagnosis?', '["Croup", "Epiglottitis", "Bronchiolitis", "Foreign body"]', 1, 'Epiglottitis is a medical emergency. (Case Files)'),
    (v_topic_id, '54: What is the classic X-ray finding for Epiglottitis?', '["Steeple sign", "Thumbprint sign", "Boot heart", "Atelectasis"]', 1, 'Thumbprint sign = swollen epiglottis. (Nelson)'),
    (v_topic_id, '55: What is the most common cause of bronchiolitis in infants?', '["Parainfluenza", "RSV", "Adenovirus", "Influenza"]', 1, 'Respiratory Syncytial Virus is the #1 cause. (Harriet Lane)'),
    (v_topic_id, '56: A child presents with "slapped cheek" rash. Diagnosis?', '["Measles", "Rubella", "Fifth Disease (Erythema Infectiosum)", "Roseola"]', 2, 'Parvovirus B19 causes Fifth Disease. (Nelson)'),
    (v_topic_id, '57: High fever for 4 days followed by a rash as the fever drops. Diagnosis?', '["Measles", "Roseola", "Rubella", "Varicella"]', 1, 'Roseola (HHV-6) is classic for fever then rash. (Case Files)'),
    (v_topic_id, '58: A child presents with Koplik spots on the buccal mucosa. Diagnosis?', '["Measles", "Mumps", "Scarlet fever", "Herpes"]', 0, 'Koplik spots are pathognomonic for Measles. (Nelson)'),
    (v_topic_id, '59: What Vitamin reduces mortality in children with Measles?', '["Vitamin C", "Vitamin A", "Vitamin D", "Zinc"]', 1, 'Vitamin A supplementation is standard for Measles. (WHO)'),
    (v_topic_id, '60: A child presents with "honey-colored" crusts on the face. Diagnosis?', '["Eczema", "Impetigo", "Cellulitis", "Acne"]', 1, 'Impetigo is often caused by S. aureus or S. pyogenes. (Harriet Lane)'),
    (v_topic_id, '61: What is the treatment for localized Impetigo?', '["Topical Mupirocin", "Oral Amoxicillin", "Topical Steroids", "Oral Acyclovir"]', 0, 'Mupirocin is the first-line topical treatment. (Case Files)'),
    (v_topic_id, '62: A child presents with a "strawberry tongue" and a sandpaper rash. Diagnosis?', '["Kawasaki disease", "Scarlet fever", "Measles", "Toxic shock"]', 1, 'Scarlet fever is caused by Group A Strep. (Nelson)'),
    (v_topic_id, '63: What is the most common complication of untreated Group A Strep pharyngitis?', '["PSGN", "Acute Rheumatic Fever", "Pneumonia", "Meningitis"]', 1, 'Antibiotics prevent Rheumatic Fever but NOT PSGN. (Harriet Lane)'),
    (v_topic_id, '64: A 15-year-old with fever and sore throat has a positive Monospot test. What should they avoid?', '["Peanuts", "Contact sports", "Sunlight", "Reading"]', 1, 'Risk of splenic rupture in EBV Mononucleosis. (Case Files)'),
    (v_topic_id, '65: What is the most common cause of UTI in children?', '["Proteus", "E. coli", "Klebsiella", "Staph saprophyticus"]', 1, 'E. coli is the leading cause. (Nelson)'),
    (v_topic_id, '66: A child presents with "currant jelly" stools and colicky abdominal pain. Diagnosis?', '["Appendicitis", "Intussusception", "Meckel diverticulum", "Gastroenteritis"]', 1, 'Intussusception involves telescoping of the bowel. (Harriet Lane)'),
    (v_topic_id, '67: What is both the diagnostic and therapeutic step for Intussusception?', '["CT scan", "Air or Contrast enema", "Surgery", "Observation"]', 1, 'Enema reduction is successful in most cases. (Case Files)'),
    (v_topic_id, '68: A neonate has not passed meconium in 48 hours and has a dilated colon. Diagnosis?', '["Cystic fibrosis", "Hirschsprung disease", "Both", "Neither"]', 2, 'Both can cause delayed meconium passage. (Nelson)'),
    (v_topic_id, '69: What is the definitive diagnosis for Hirschsprung disease?', '["X-ray", "Contrast enema", "Rectal suction biopsy", "Stool culture"]', 2, 'Biopsy shows absence of ganglion cells. (Harriet Lane)'),
    (v_topic_id, '70: A 3-week-old infant presents with non-bilious, projectile vomiting. Diagnosis?', '["GERD", "Pyloric stenosis", "Intussusception", "Volvulus"]', 1, 'Pyloric stenosis typically presents at 3-6 weeks. (Case Files)'),
    (v_topic_id, '71: What electrolyte abnormality is classic for Pyloric Stenosis?', '["Hypokalemic, hypochloremic metabolic alkalosis", "Hyperkalemia", "Metabolic acidosis", "Hyponatremia"]', 0, 'Loss of HCl and K+ in gastric contents. (Nelson)'),
    (v_topic_id, '72: A child presents with "painless" rectal bleeding. Diagnosis?', '["Anal fissure", "Meckel diverticulum", "IBD", "Polyps"]', 1, 'Meckel''s is a common cause of painless lower GI bleed in kids. (Harriet Lane)'),
    (v_topic_id, '73: What is the most common cause of primary nephrotic syndrome in children?', '["Membranous nephropathy", "Minimal Change Disease", "FSGS", "Post-strep GN"]', 1, 'MCD responds well to steroids. (Case Files)'),
    (v_topic_id, '74: A child has periorbital edema and cola-colored urine after a sore throat. Diagnosis?', '["Nephrotic syndrome", "Post-streptococcal glomerulonephritis", "UTI", "Kidney stone"]', 1, 'PSGN follows a Strep infection. (Nelson)'),
    (v_topic_id, '75: What is the most common cause of pediatric hypertension?', '["Essential hypertension", "Renal parenchymal disease", "Coarctation of the aorta", "Pheochromocytoma"]', 1, 'Secondary causes are more common in prepubertal children. (Harriet Lane)'),
    (v_topic_id, '76: A child presents with a "mid-systolic" murmur that is loudest when supine and disappears when standing. Diagnosis?', '["VSD", "Still''s murmur (Innocent)", "Mitral regurgitation", "AS"]', 1, 'Classic Still''s murmur features. (Case Files)'),
    (v_topic_id, '77: What is the most common cyanotic congenital heart disease in the neonatal period?', '["Tetralogy of Fallot", "Transposition of the Great Arteries", "ASD", "VSD"]', 1, 'TGA is the most common cyanotic lesion presenting in the first week. (Nelson)'),
    (v_topic_id, '78: What is the most common congenital heart defect overall?', '["ASD", "VSD", "PDA", "ToF"]', 1, 'Ventricular Septal Defect is #1. (Harriet Lane)'),
    (v_topic_id, '79: A neonate has a "machinery" murmur at the upper left sternal border. Diagnosis?', '["VSD", "PDA", "ASD", "Coarctation"]', 1, 'Patent Ductus Arteriosus. (Case Files)'),
    (v_topic_id, '80: What is the drug used to close a PDA?', '["Prostaglandin E1", "Indomethacin", "Alprostadil", "Oxygen"]', 1, 'NSAIDS like Indomethacin or Ibuprofen inhibit prostaglandins to close the ductus. (Nelson)'),
    (v_topic_id, '81: What is the drug used to keep a PDA open in ductal-dependent lesions?', '["Indomethacin", "Prostaglandin E1", "Aspirin", "Digoxin"]', 1, 'PGE1 maintains patency. (Harriet Lane)'),
    (v_topic_id, '82: A child presents with a "boot-shaped" heart on X-ray. Diagnosis?', '["TGA", "Tetralogy of Fallot", "TAPVR", "Ebstein anomaly"]', 1, 'ToF features right ventricular hypertrophy. (Case Files)'),
    (v_topic_id, '83: What is a "Tet spell"?', '["A seizure", "Acute cyanotic episode in ToF", "A fainting spell", "A migraine"]', 1, 'Often relieved by knee-chest positioning. (Nelson)'),
    (v_topic_id, '84: A child has higher blood pressure in the arms than the legs. Diagnosis?', '["VSD", "Coarctation of the aorta", "PDA", "ToF"]', 1, 'Classic sign of post-ductal coarctation. (Harriet Lane)'),
    (v_topic_id, '85: What is the most common cause of acquired heart disease in children in developed countries?', '["Rheumatic fever", "Kawasaki disease", "Endocarditis", "Myocarditis"]', 1, 'Kawasaki can lead to coronary artery aneurysms. (Case Files)'),
    (v_topic_id, '86: What is the treatment for Kawasaki disease to prevent aneurysms?', '["Aspirin and IVIG", "Antibiotics", "Steroids", "Surgery"]', 0, 'IVIG must be given within the first 10 days. (Nelson)'),
    (v_topic_id, '87: A child presents with a "strawberry tongue," fever for 6 days, and red eyes. Diagnosis?', '["Measles", "Scarlet fever", "Kawasaki disease", "Toxic shock"]', 2, 'Fever >= 5 days is a key diagnostic criterion. (Harriet Lane)'),
    (v_topic_id, '88: What is the most common cause of preventable intellectual disability worldwide?', '["Down syndrome", "Fetal alcohol syndrome", "Congenital hypothyroidism (Iodine deficiency)", "Lead poisoning"]', 2, 'Universal newborn screening prevents cretinism. (Nelson)'),
    (v_topic_id, '89: A child has a "musty" odor and fair skin. Diagnosis?', '["Albinism", "Phenylketonuria (PKU)", "Galactosemia", "Homocystinuria"]', 1, 'PKU requires a low-phenylalanine diet. (Case Files)'),
    (v_topic_id, '90: What is the "Rule of 3s" for infant colic?', '["3 hours/day, 3 days/week, for 3 weeks", "3 months old, 3 cries, 3 feeds", "None", "All"]', 0, 'Wessel criteria for colic. (Nelson)'),
    (v_topic_id, '91: At what age should a child double their birth weight?', '["2 months", "4-5 months", "1 year", "2 years"]', 1, 'Birth weight doubles by 5 months, triples by 1 year. (Harriet Lane)'),
    (v_topic_id, '92: A child''s birth weight has tripled. Age?', '["6 months", "12 months", "24 months", "3 years"]', 1, 'Triples at 12 months. (Case Files)'),
    (v_topic_id, '93: At what age should a child double their birth length?', '["1 year", "2 years", "4 years", "6 years"]', 2, 'Length doubles by age 4. (Nelson)'),
    (v_topic_id, '94: When does the anterior fontanelle typically close?', '["2 months", "12-18 months", "3 years", "5 years"]', 1, 'Posterior closes at 2m; Anterior at 12-18m. (Harriet Lane)'),
    (v_topic_id, '95: A child has "bow legs" (genu varum). When is this normal?', '["Birth to 2 years", "3-5 years", "Adolescence", "Never"]', 0, 'Physiologic bowing is normal in the first 2 years. (Case Files)'),
    (v_topic_id, '96: A child has "knock knees" (genu valgum). When is this most common?', '["Birth", "3-4 years", "10 years", "Never"]', 1, 'Physiologic valgus peaks at 3-4 years. (Nelson)'),
    (v_topic_id, '97: What is the most common cause of a limp in a child with a recent viral infection?', '["Septic arthritis", "Transient synovitis", "Lyme disease", "Osteomyelitis"]', 1, 'Transient synovitis (toxic synovitis) is a benign, self-limiting limp. (Harriet Lane)'),
    (v_topic_id, '98: A child has a high fever and won''t move the hip joint. WBC and ESR are very high. Diagnosis?', '["Transient synovitis", "Septic arthritis", "Growing pains", "Scoliosis"]', 1, 'Septic arthritis is an orthopedic emergency. (Case Files)'),
    (v_topic_id, '99: A 12-year-old obese male has hip pain and a limp. Diagnosis?', '["Legg-Calve-Perthes", "Slipped Capital Femoral Epiphysis (SCFE)", "Osgood-Schlatter", "ACL tear"]', 1, 'SCFE is classic in obese adolescents. (Nelson)'),
    (v_topic_id, '100: A 5-year-old male has painless hip pain and a limp. X-ray shows flattening of the femoral head. Diagnosis?', '["SCFE", "Legg-Calve-Perthes disease", "Toxic synovitis", "Septic arthritis"]', 1, 'Avascular necrosis of the femoral head in children. (Harriet Lane)');
